def solve(s):
    """Balanced brackets checker.
    Returns True only if brackets are balanced and at least one bracket pair is present.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())
    stack = []
    found = False
    for ch in s:
        if ch in opening:
            stack.append(ch)
            found = True
        elif ch in matching:
            found = True
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack and found

