def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / operators with integer operands. Division truncates toward zero.
    """
    if not tokens:
        return 0
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):  # operator
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # Python's int division of a / b truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

